// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 seedTimestamp) public {
        vm.assume(caller != address(0));
        vm.assume(caller != 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        // seed market and set caller's kilos to 0
        c.seedMarket(1000);
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.buyDrugs{value: 1 ether}();
        vm.prank(caller);
        c.collectDrugs(address(0));
        // now caller has kilos > 0, we need to reset kilos for getFreeKilo
        // we cannot reset kilos directly, so use a fresh account
        address fresh = address(0x1234);
        vm.deal(fresh, 0);
        vm.prank(fresh);
        c.getFreeKilo();
        // after getFreeKilo, lastCollect[fresh] should be block.timestamp
        assertTrue(c.lastCollect(fresh) == block.timestamp, "lastCollect should be updated to block.timestamp");
    }
}

